interface.definition:
a!localVariables(
  local!appdetails: if(
    a!isNotNullOrEmpty(ri!appid),
    #"_a-0000ef87-dc84-8000-9e58-011c48011c48_1316451"(AppId: ri!appid),
    null()
  ),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1136273"(application: local!appdetails)
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            if(
              ri!isUpdate,
              {
                a!save(
                  target: local!appdetails[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/1c4afd49-abdc-4a12-b126-5e2397abec16"],
                  value: loggedInUser()
                ),
                a!save(
                  target: local!appdetails[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/2ae72cda-12f5-48a2-bf61-706f697f6734"],
                  value: now()
                )
              },
              {
                a!save(
                  target: ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b7f7118c-46d1-454a-b1e5-43d6c512d680"],
                  value: loggedInUser()
                ),
                a!save(
                  target: ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3d842534-8460-4cf1-943a-e3bf1a162b9a"],
                  value: now()
                ),
                a!save(
                  target: ri!application[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b0983308-9603-4f16-b22c-c1fe878df61b"],
                  value: true()
                )
              }
            ),
            a!save(
              target: ri!application,
              value: local!appdetails
            ),
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: if(
        a!isNotNullOrEmpty(ri!isUpdate),
        "Update Application",
        "Create Application"
      ),
      secondaryText: if(
        a!isNotNullOrEmpty(ri!isUpdate),
        "Update Application Details",
        "Enter Application details"
      ),
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
